package main

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"math"
	"sync"
)

// us_2026.json is generated by tools/build_taxdata.py (IRS / SSA federal figures,
// Tax Foundation state tables). It covers wage income only: no credits beyond the
// state exemption credits, no AMT, itemizing, or multi-state allocation.
//
//go:embed taxdata/us_2026.json
var taxDataJSON []byte

// Bracket is one marginal rate, starting at From dollars of taxable income.
type Bracket struct {
	From int64
	Rate float64
}

// UnmarshalJSON reads the compact [from, rate] form used in the data file.
func (b *Bracket) UnmarshalJSON(data []byte) error {
	var pair [2]float64
	if err := json.Unmarshal(data, &pair); err != nil {
		return err
	}
	b.From, b.Rate = int64(pair[0]), pair[1]
	return nil
}

type StateTax struct {
	Name              string               `json:"name"`
	Type              string               `json:"type"` // none, flat, brackets
	Source            string               `json:"source"`
	Year              int                  `json:"year"`
	Brackets          map[string][]Bracket `json:"brackets"`
	StandardDeduction map[string]int64     `json:"standardDeduction"`
	Exemption         map[string]int64     `json:"exemption"`
	Credit            map[string]int64     `json:"credit"`
}

type TaxData struct {
	Year    int `json:"year"`
	Federal struct {
		Source            string               `json:"source"`
		Brackets          map[string][]Bracket `json:"brackets"`
		StandardDeduction map[string]int64     `json:"standardDeduction"`
		SocialSecurity    struct {
			Rate     float64 `json:"rate"`
			WageBase int64   `json:"wageBase"`
		} `json:"socialSecurity"`
		Medicare struct {
			Rate           float64          `json:"rate"`
			AdditionalRate float64          `json:"additionalRate"`
			Threshold      map[string]int64 `json:"threshold"`
		} `json:"medicare"`
	} `json:"federal"`
	States map[string]StateTax `json:"states"`
}

type TaxInput struct {
	Wages      int64   `json:"wages"`      // taxable wages (salary, bonus, signing, vested RSUs)
	PreTax401k int64   `json:"preTax401k"` // employee contribution; lowers income tax, not FICA
	Filing     string  `json:"filing"`     // single, married, head
	State      string  `json:"state"`      // 2-letter code
	LocalPct   float64 `json:"localPct"`   // flat local/city income tax, 0-100
}

type TaxResult struct {
	Federal        int64   `json:"federal"`
	SocialSecurity int64   `json:"socialSecurity"`
	Medicare       int64   `json:"medicare"`
	State          int64   `json:"state"`
	Local          int64   `json:"local"`
	Total          int64   `json:"total"`
	EffectiveRate  float64 `json:"effectiveRate"`
	StateName      string  `json:"stateName"`
	StateSource    string  `json:"stateSource"`
	Year           int     `json:"year"`
}

var (
	taxOnce sync.Once
	taxData *TaxData
	taxErr  error
)

func loadTaxData() (*TaxData, error) {
	taxOnce.Do(func() {
		var td TaxData
		if err := json.Unmarshal(taxDataJSON, &td); err != nil {
			taxErr = fmt.Errorf("tax data: %w", err)
			return
		}
		taxData = &td
	})
	return taxData, taxErr
}

// bracketTax applies marginal rates; income below the first bracket's start is untaxed.
func bracketTax(income float64, brackets []Bracket) float64 {
	tax := 0.0
	for i, b := range brackets {
		if income <= float64(b.From) {
			break
		}
		top := income
		if i+1 < len(brackets) && float64(brackets[i+1].From) < top {
			top = float64(brackets[i+1].From)
		}
		tax += (top - float64(b.From)) * b.Rate
	}
	return tax
}

func roundDollars(v float64) int64 { return int64(math.Round(v)) }

func ComputeTax(in TaxInput) (TaxResult, error) {
	td, err := loadTaxData()
	if err != nil {
		return TaxResult{}, err
	}
	fedBrackets, ok := td.Federal.Brackets[in.Filing]
	if !ok {
		return TaxResult{}, fmt.Errorf("unknown filing status %q", in.Filing)
	}
	st, ok := td.States[in.State]
	if !ok {
		return TaxResult{}, fmt.Errorf("unknown state %q", in.State)
	}
	res := TaxResult{StateName: st.Name, StateSource: st.Source, Year: st.Year}
	if in.Wages <= 0 {
		return res, nil
	}
	wages := float64(in.Wages)
	afterRetirement := math.Max(0, wages-float64(in.PreTax401k))

	fedTaxable := math.Max(0, afterRetirement-float64(td.Federal.StandardDeduction[in.Filing]))
	res.Federal = roundDollars(bracketTax(fedTaxable, fedBrackets))

	ss := td.Federal.SocialSecurity
	res.SocialSecurity = roundDollars(math.Min(wages, float64(ss.WageBase)) * ss.Rate)
	mc := td.Federal.Medicare
	medicare := wages * mc.Rate
	if over := wages - float64(mc.Threshold[in.Filing]); over > 0 {
		medicare += over * mc.AdditionalRate
	}
	res.Medicare = roundDollars(medicare)

	if st.Type != "none" {
		// The state table covers single and married; head of household uses the single schedule.
		status := in.Filing
		if status != "married" {
			status = "single"
		}
		taxable := math.Max(0, afterRetirement-float64(st.StandardDeduction[status])-float64(st.Exemption[status]))
		res.State = roundDollars(math.Max(0, bracketTax(taxable, st.Brackets[status])-float64(st.Credit[status])))
	}
	res.Local = roundDollars(afterRetirement * in.LocalPct / 100)

	res.Total = res.Federal + res.SocialSecurity + res.Medicare + res.State + res.Local
	res.EffectiveRate = float64(res.Total) / wages
	return res, nil
}
